package net.civeira.phylax.features.document.template.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.template.domain.Template;
import net.civeira.phylax.features.document.template.domain.event.TemplateEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class TemplateEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<TemplateEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final Template entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
